/* === Reset & Base === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0a0a23;
  --gold: #feac32;
  --blue: #002ead;
  --white: #ffffff;
  --light-gray: #f5f5f5;
  --mid-gray: #d0d0d5;
  --text: #1b1b32;
  --text-light: #6a6a8e;
  --radius: 6px;
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --font: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

html { font-size: 16px; scroll-behavior: smooth; }
body { font-family: var(--font); color: var(--text); background: var(--white); line-height: 1.6; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; display: block; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* === Header === */
.site-header { background: var(--navy); color: var(--white); position: sticky; top: 0; z-index: 100; }
.header-inner { max-width: 1200px; margin: 0 auto; padding: 0.75rem 1.5rem; display: flex; align-items: center; gap: 1rem; }
.logo { font-size: 1.25rem; font-weight: 700; color: var(--white); text-decoration: none; display: flex; align-items: center; gap: 0.5rem; white-space: nowrap; }
.logo-icon { width: 32px; height: 32px; background: var(--gold); border-radius: 4px; display: flex; align-items: center; justify-content: center; font-weight: 800; color: var(--navy); font-size: 1rem; flex-shrink: 0; }
.search-bar { flex: 1; max-width: 480px; position: relative; }
.search-bar input {
  width: 100%; padding: 0.5rem 0.75rem 0.5rem 2.25rem;
  border: 1px solid rgba(255,255,255,0.2); border-radius: var(--radius);
  background: rgba(255,255,255,0.1); color: var(--white); font-size: 0.875rem;
}
.search-bar input::placeholder { color: rgba(255,255,255,0.5); }
.search-bar svg { position: absolute; left: 0.6rem; top: 50%; transform: translateY(-50%); opacity: 0.5; }
.nav-links { display: flex; gap: 1.25rem; align-items: center; }
.nav-links a { color: var(--white); font-size: 0.9rem; font-weight: 500; white-space: nowrap; }
.nav-links a:hover { color: var(--gold); text-decoration: none; }

/* Hamburger */
.hamburger { display: none; background: none; border: none; color: var(--white); font-size: 1.5rem; padding: 0.25rem; }
.mobile-menu { display: none; background: var(--navy); padding: 0.75rem 1.5rem 1rem; }
.mobile-menu.active { display: block; }
.mobile-menu a { display: block; color: var(--white); padding: 0.5rem 0; font-size: 0.95rem; }
.mobile-menu a:hover { color: var(--gold); text-decoration: none; }

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hamburger { display: block; }
  .search-bar { max-width: none; }
  .header-inner { flex-wrap: wrap; }
  .search-bar { order: 3; flex-basis: 100%; }
}

/* === Banner === */
.banner {
  background: var(--gold); text-align: center;
  padding: 0.6rem 1rem; font-weight: 600; font-size: 0.95rem; color: var(--navy);
}
.banner a { color: var(--navy); text-decoration: underline; }

/* === Container === */
.container { max-width: 1200px; margin: 0 auto; padding: 2rem 1.5rem; }

/* === Featured Article === */
.featured-card {
  position: relative; border-radius: var(--radius); overflow: hidden;
  margin-bottom: 2.5rem; background: var(--light-gray); box-shadow: var(--shadow);
}
.featured-card .thumb {
  width: 100%; height: 360px; object-fit: cover;
  background: linear-gradient(135deg, #1a1a40 0%, #0a0a23 100%);
}
.featured-card .overlay {
  position: absolute; bottom: 0; left: 0; right: 0;
  background: linear-gradient(transparent, rgba(0,0,0,0.85));
  padding: 2rem; color: var(--white);
}
.featured-card .tag { display: inline-block; background: var(--gold); color: var(--navy); padding: 0.2rem 0.6rem; border-radius: 3px; font-size: 0.75rem; font-weight: 700; text-transform: uppercase; margin-bottom: 0.5rem; }
.featured-card .overlay h2 { font-size: 1.5rem; margin-bottom: 0.75rem; line-height: 1.3; }
.featured-card .author-row { display: flex; align-items: center; gap: 0.5rem; font-size: 0.85rem; color: rgba(255,255,255,0.8); }
.avatar { width: 28px; height: 28px; border-radius: 50%; background: var(--gold); display: inline-flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.7rem; color: var(--navy); flex-shrink: 0; }

/* === Article Grid === */
.section-title { font-size: 1.25rem; font-weight: 700; margin-bottom: 1.25rem; }
.article-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-bottom: 2rem; }
.article-card {
  background: var(--white); border-radius: var(--radius); overflow: hidden;
  box-shadow: var(--shadow); transition: transform 0.2s, box-shadow 0.2s;
}
.article-card:hover { transform: translateY(-3px); box-shadow: 0 6px 20px rgba(0,0,0,0.12); }
.article-card .card-thumb {
  width: 100%; height: 180px; object-fit: cover;
  background: linear-gradient(135deg, #1a1a40, #2a2a5a);
}
.article-card .card-body { padding: 1rem; }
.article-card .tag {
  display: inline-block; padding: 0.15rem 0.5rem; border-radius: 3px;
  font-size: 0.7rem; font-weight: 700; text-transform: uppercase; margin-bottom: 0.4rem;
}
.tag-ai { background: #e8d5f5; color: #6b21a8; }
.tag-scraping { background: #d1fae5; color: #065f46; }
.tag-databases { background: #dbeafe; color: #1e40af; }
.tag-elasticsearch { background: #fef3c7; color: #92400e; }
.tag-data-eng { background: #ffe4e6; color: #9f1239; }
.tag-python { background: #d1fae5; color: #065f46; }
.tag-automation { background: #e0e7ff; color: #3730a3; }
.tag-nodejs { background: #d1fae5; color: #065f46; }
.tag-sheets { background: #dbeafe; color: #1e40af; }
.tag-default { background: var(--mid-gray); color: var(--text); }

.article-card .card-title {
  font-size: 0.95rem; font-weight: 600; line-height: 1.4;
  margin-bottom: 0.75rem; color: var(--text);
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.article-card .card-title a { color: inherit; }
.article-card .card-title a:hover { color: var(--blue); text-decoration: none; }
.article-card .card-meta { display: flex; align-items: center; gap: 0.5rem; font-size: 0.8rem; color: var(--text-light); }

.load-more-wrap { text-align: center; margin: 1.5rem 0 1rem; }
.btn-load-more {
  background: var(--navy); color: var(--white);
  padding: 0.7rem 2rem; border: none; border-radius: var(--radius);
  font-size: 0.95rem; font-weight: 600; transition: background 0.2s;
}
.btn-load-more:hover { background: #1b1b44; }

@media (max-width: 900px) { .article-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 560px) { .article-grid { grid-template-columns: 1fr; } }

/* === Tag Pages === */
.tag-header { margin-bottom: 1.5rem; }
.tag-header h1 { font-size: 1.75rem; font-weight: 800; text-transform: uppercase; margin-bottom: 0.25rem; }
.tag-header .post-count { color: var(--text-light); font-size: 0.95rem; }
.popular-tags { display: flex; flex-wrap: wrap; gap: 0.6rem; margin-bottom: 2rem; }
.popular-tags .ptag {
  background: var(--light-gray); padding: 0.35rem 0.75rem; border-radius: 20px;
  font-size: 0.8rem; font-weight: 500; color: var(--text); white-space: nowrap;
}
.popular-tags .ptag span { color: var(--text-light); margin-left: 0.25rem; }

/* === Learn Page === */
.welcome-box {
  background: var(--light-gray); border-radius: var(--radius); padding: 1.5rem 2rem;
  margin-bottom: 2rem; text-align: center;
}
.welcome-box p { color: var(--text-light); margin-bottom: 0.75rem; }
.welcome-box .btn-signin {
  background: var(--gold); color: var(--navy); border: none;
  padding: 0.6rem 1.5rem; border-radius: var(--radius); font-weight: 600; font-size: 0.9rem;
}
.curriculum-section { margin-bottom: 2.5rem; }
.curriculum-section h2 { font-size: 1.2rem; font-weight: 700; margin-bottom: 1rem; padding-bottom: 0.5rem; border-bottom: 2px solid var(--light-gray); }
.cert-list { display: flex; flex-direction: column; gap: 0.5rem; }
.cert-item {
  display: flex; align-items: center; gap: 0.75rem; padding: 0.75rem 1rem;
  background: var(--white); border: 1px solid var(--mid-gray); border-radius: var(--radius);
  transition: background 0.15s;
}
.cert-item:hover { background: var(--light-gray); }
.cert-icon { width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1rem; flex-shrink: 0; }
.cert-item span { font-weight: 500; font-size: 0.95rem; }
.cert-item .beta-badge { font-size: 0.7rem; background: var(--gold); color: var(--navy); padding: 0.1rem 0.4rem; border-radius: 3px; font-weight: 700; margin-left: 0.5rem; }

.challenge-box {
  background: linear-gradient(135deg, var(--navy), #1b1b44); color: var(--white);
  border-radius: var(--radius); padding: 2rem; text-align: center; margin-bottom: 2.5rem;
}
.challenge-box h2 { font-size: 1.3rem; margin-bottom: 1rem; }
.challenge-box .btn-challenge {
  display: inline-block; background: var(--gold); color: var(--navy);
  padding: 0.6rem 1.5rem; border-radius: var(--radius); font-weight: 600; font-size: 0.9rem;
  margin: 0.25rem;
}

/* === Donate Page === */
.donate-hero {
  text-align: center; padding: 3rem 1.5rem; background: var(--navy); color: var(--white);
  margin: 0 -1.5rem 2rem;
}
.donate-hero h1 { font-size: 2rem; margin-bottom: 1rem; }
.donate-hero p { max-width: 640px; margin: 0 auto 2rem; color: rgba(255,255,255,0.85); line-height: 1.7; }

.amount-tabs { display: flex; justify-content: center; gap: 0.5rem; margin-bottom: 1rem; flex-wrap: wrap; }
.amount-tab {
  background: rgba(255,255,255,0.1); border: 2px solid rgba(255,255,255,0.25);
  color: var(--white); padding: 0.6rem 1.5rem; border-radius: var(--radius);
  font-size: 1.1rem; font-weight: 700; transition: all 0.2s; min-width: 70px;
}
.amount-tab:hover { border-color: var(--gold); }
.amount-tab.active { background: var(--gold); color: var(--navy); border-color: var(--gold); }
.donate-desc { text-align: center; color: rgba(255,255,255,0.8); margin-bottom: 1.5rem; font-size: 0.95rem; }
.btn-donate {
  display: block; width: 240px; margin: 0 auto 0.75rem; padding: 0.85rem;
  background: var(--gold); color: var(--navy); border: none; border-radius: var(--radius);
  font-size: 1.1rem; font-weight: 700; transition: background 0.2s;
}
.btn-donate:hover { background: #f5a623; }
.donate-sub { text-align: center; font-size: 0.8rem; color: rgba(255,255,255,0.6); }
.donate-sub a { color: var(--gold); }

.benefits-section, .initiatives-section, .achievements-section { margin-bottom: 2.5rem; }
.benefits-section h2, .initiatives-section h2, .achievements-section h2, .faq-section h2 {
  font-size: 1.25rem; font-weight: 700; margin-bottom: 1rem;
}
.benefits-list li, .initiatives-list li, .achievements-list li {
  padding: 0.5rem 0; padding-left: 1.5rem; position: relative; line-height: 1.5;
}
.benefits-list li::before { content: "✓"; position: absolute; left: 0; color: var(--gold); font-weight: 700; }
.initiatives-list li::before { content: "→"; position: absolute; left: 0; color: var(--blue); font-weight: 700; }
.achievements-list li::before { content: "★"; position: absolute; left: 0; color: var(--gold); }

/* FAQ Accordion */
.faq-section { margin-bottom: 2.5rem; }
.faq-item { border-bottom: 1px solid var(--mid-gray); }
.faq-question {
  width: 100%; background: none; border: none; text-align: left;
  padding: 1rem 2rem 1rem 0; font-size: 0.95rem; font-weight: 600;
  color: var(--text); position: relative; line-height: 1.4;
}
.faq-question::after {
  content: "+"; position: absolute; right: 0; top: 50%; transform: translateY(-50%);
  font-size: 1.25rem; font-weight: 400; color: var(--text-light); transition: transform 0.2s;
}
.faq-item.open .faq-question::after { content: "−"; }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.3s ease, padding 0.3s ease; }
.faq-item.open .faq-answer { max-height: 200px; padding-bottom: 1rem; }
.faq-answer p { color: var(--text-light); font-size: 0.9rem; line-height: 1.6; }

/* === Footer === */
.site-footer { background: var(--navy); color: rgba(255,255,255,0.7); padding: 2.5rem 1.5rem 1.5rem; }
.footer-inner { max-width: 1200px; margin: 0 auto; }
.footer-mission { max-width: 720px; margin-bottom: 1.5rem; line-height: 1.7; font-size: 0.9rem; }
.footer-heading { font-weight: 700; color: var(--white); margin-bottom: 0.5rem; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.05em; }
.footer-links { display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; margin-bottom: 1.5rem; }
.footer-links a { color: rgba(255,255,255,0.6); font-size: 0.85rem; }
.footer-links a:hover { color: var(--gold); text-decoration: none; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 1rem; font-size: 0.8rem; color: rgba(255,255,255,0.4); }

